window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a6be2eb29f45e3c9"]={"versions": [{"id": "FIG-a6be2eb29f45e3c9", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Modul-Architekturdiagramm der AUTOSAR-Basissoftware (BSW) für die LIN-Kommunikation. Dargestellt ist die vertikale Schichtung und Einbettung des LIN-Interface-Moduls zwischen dem PDU-Router und den hardwarenahen LIN-Treibern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in drei farblich codierte Architekturschichten mit folgenden Software-Entitäten:</p>\n<ul class=\"fig-list\"><li>Obere Schicht (blau unterlegt, System-Services / Routing-Ebene): Enthält den Baustein <code>PDU Router</code>.\n</li><li>Mittlere Schicht (<em>Communication HW Abstraction</em>, grün unterlegt): Beinhaltet den Baustein <code>LIN Interface (incl. LIN TP and LIN transceiver functionality)</code>.\n</li><li>Untere Schicht (<em>Communication Drivers</em>, rot unterlegt): Beinhaltet zwei parallele Treiberinstanzen bzw. Module, <code>LIN Driver 1</code> und <code>LIN Driver 2</code>.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Verbindungspfade:</p>\n<ul class=\"fig-list\"><li>Ein vertikaler Doppelpfeil zwischen <code>PDU Router</code> und <code>LIN Interface (incl. LIN TP and LIN transceiver functionality)</code> ist mit <code>N-PDU</code> beschriftet.\n</li><li>Ein verzweigter Pfeil verbindet das <code>LIN Interface (incl. LIN TP and LIN transceiver functionality)</code> mit den beiden Treibern <code>LIN Driver 1</code> und <code>LIN Driver 2</code>; der Stamm dieses Verbindungspfads ist mit <code>L-PDU</code> beschriftet. Die Pfeilspitzen weisen nach oben zum LIN Interface sowie nach unten zu den jeweiligen LIN-Treibern.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite zeitliche Sequenzabläufe. Die Pfeilverbindungen symbolisieren den bidirektionalen Datenaustausch von Protokolldateneinheiten (PDUs):</p>\n<ul class=\"fig-list\"><li>Austausch von Netzwerk-PDUs (<code>N-PDU</code>) in Sende- und Empfangsrichtung zwischen dem PDU Router und dem LIN Interface (inklusive Transportprotokoll LinTp).\n</li><li>Austausch von LIN-spezifischen Verbindungsdaten (<code>L-PDU</code>) zwischen dem LIN Interface und mehreren zugrunde liegenden LIN-Treibern (<code>LIN Driver 1</code>, <code>LIN Driver 2</code>) zur Anbindung mehrerer LIN-Kanäle oder -Controller.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Integrationsgrenzen und Verantwortlichkeiten des LIN-Interface-Moduls in der AUTOSAR-Architektur. Das Modul kapselt die LIN-Treiber-Hardwareabstraktion sowie integrierte Transport- und Transceiver-Funktionen und stellt dem PDU Router eine einheitliche PDU-Schnittstelle bereit. Die Verzweigung verdeutlicht die Multi-Channel-Fähigkeit bzw. die Unterstützung mehrerer Treiberinstanzen unterhalb eines einheitlichen Interfaces.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5d2af1417ba579a7", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Modul-Architekturdiagramm der AUTOSAR-Basissoftware (BSW) für die LIN-Kommunikation. Dargestellt ist die vertikale Schichtung und Einbettung des LIN-Interface-Moduls zwischen dem PDU-Router und den hardwarenahen LIN-Treibern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in drei farblich codierte Architekturschichten mit folgenden Software-Entitäten:</p>\n<ul class=\"fig-list\"><li>Obere Schicht (blau unterlegt, System-Services / Routing-Ebene): Enthält den Baustein <code>PDU Router</code>.\n</li><li>Mittlere Schicht (<em>Communication HW Abstraction</em>, grün unterlegt): Beinhaltet den Baustein <code>LIN Interface (incl. LinTp)</code>.\n</li><li>Untere Schicht (<em>Communication Drivers</em>, rot unterlegt): Beinhaltet zwei parallele Treiberinstanzen bzw. Module, <code>LIN Driver 1</code> und <code>LIN Driver 2</code>.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Verbindungspfade:</p>\n<ul class=\"fig-list\"><li>Ein vertikaler Doppelpfeil zwischen <code>PDU Router</code> und <code>LIN Interface (incl. LinTp)</code> ist mit <code>N-PDU</code> beschriftet.\n</li><li>Ein verzweigter Pfeil verbindet das <code>LIN Interface (incl. LinTp)</code> mit den beiden Treibern <code>LIN Driver 1</code> und <code>LIN Driver 2</code>; der Stamm dieses Verbindungspfads ist mit <code>L-PDU</code> beschriftet. Die Pfeilspitzen weisen nach oben zum LIN Interface sowie nach unten zu den jeweiligen LIN-Treibern.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite zeitliche Sequenzabläufe. Die Pfeilverbindungen symbolisieren den bidirektionalen Datenaustausch von Protokolldateneinheiten (PDUs):</p>\n<ul class=\"fig-list\"><li>Austausch von Netzwerk-PDUs (<code>N-PDU</code>) in Sende- und Empfangsrichtung zwischen dem PDU Router und dem LIN Interface (inklusive LinTp).\n</li><li>Austausch von LIN-spezifischen Verbindungsdaten (<code>L-PDU</code>) zwischen dem LIN Interface und mehreren zugrunde liegenden LIN-Treibern (<code>LIN Driver 1</code>, <code>LIN Driver 2</code>) zur Anbindung mehrerer LIN-Kanäle oder -Controller.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Integrationsgrenzen und Verantwortlichkeiten des LIN-Interface-Moduls in der AUTOSAR-Architektur. Das Modul kapselt die LIN-Treiber-Hardwareabstraktion sowie integrierte Transport- und Transceiver-Funktionen und stellt dem PDU Router eine einheitliche PDU-Schnittstelle bereit. Die Verzweigung verdeutlicht die Multi-Channel-Fähigkeit bzw. die Unterstützung mehrerer Treiberinstanzen unterhalb eines einheitlichen Interfaces.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f172b47124306d00", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Modul-Architekturdiagramm der AUTOSAR-Basissoftware (BSW) für die LIN-Kommunikation. Dargestellt ist die vertikale Schichtung und Einbettung des LIN-Interface-Moduls zwischen dem PDU-Router und den hardwarenahen LIN-Treibern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in drei farblich codierte Architekturschichten mit folgenden Software-Entitäten:</p>\n<ul class=\"fig-list\"><li>Obere Schicht (blau unterlegt, System-Services / Routing-Ebene): Enthält den Baustein <code>PDU Router</code>.\n</li><li>Mittlere Schicht (<em>Communication HW Abstraction</em>, grün unterlegt): Beinhaltet den Baustein <code>LIN Interface (incl. LinTp)</code>.\n</li><li>Untere Schicht (<em>Communication Drivers</em>, rot unterlegt): Beinhaltet links den Baustein <code>LIN Driver 1</code> und rechts einen Baustein mit der fehlerhaften zweizeiligen Beschriftung <code>LPduR_LinIfTxConfirmation(LinTxPduId)</code> über <code>IN Driver 2</code>.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Verbindungspfade:</p>\n<ul class=\"fig-list\"><li>Ein vertikaler Doppelpfeil zwischen <code>PDU Router</code> und <code>LIN Interface (incl. LinTp)</code> ist mit <code>N-PDU</code> beschriftet.\n</li><li>Ein verzweigter Pfeil verbindet das <code>LIN Interface (incl. LinTp)</code> mit den beiden Treiberblöcken; der Stamm dieses Verbindungspfads ist mit <code>L-PDU</code> beschriftet. Die Pfeilspitzen weisen nach oben zum LIN Interface sowie nach unten zu den beiden Treiberblöcken.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite zeitliche Sequenzabläufe. Die Pfeilverbindungen symbolisieren den bidirektionalen Datenaustausch von Protokolldateneinheiten (PDUs):</p>\n<ul class=\"fig-list\"><li>Austausch von Netzwerk-PDUs (<code>N-PDU</code>) in Sende- und Empfangsrichtung zwischen dem PDU Router und dem LIN Interface (inklusive LinTp).\n</li><li>Austausch von LIN-spezifischen Verbindungsdaten (<code>L-PDU</code>) zwischen dem LIN Interface und mehreren zugrunde liegenden LIN-Treibern (<code>LIN Driver 1</code>, <code>LIN Driver 2</code>) zur Anbindung mehrerer LIN-Kanäle oder -Controller.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Integrationsgrenzen und Verantwortlichkeiten des LIN-Interface-Moduls in der AUTOSAR-Architektur. Das Modul kapselt die LIN-Treiber-Hardwareabstraktion sowie integrierte LinTp-Funktionalität und stellt dem PDU Router eine einheitliche PDU-Schnittstelle bereit. Die Verzweigung verdeutlicht die Multi-Channel-Fähigkeit bzw. die Unterstützung mehrerer Treiberinstanzen unterhalb eines einheitlichen Interfaces. Die im rechten Treiberkasten abgedruckte Callback-Signatur <code>LPduR_LinIfTxConfirmation(LinTxPduId)</code> stellt einen Satzfehler im Diagrammlayout dar und definiert keine eigenständige Architekturkomponente.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4e8873625241ef7c", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schichten- und Modul-Architekturdiagramm der AUTOSAR-Basissoftware (BSW) für die LIN-Kommunikation. Dargestellt ist die vertikale Schichtung und Einbettung des LIN-Interface-Moduls zwischen dem PDU-Router und den hardwarenahen LIN-Treibern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in drei farblich codierte Architekturschichten mit folgenden Software-Entitäten:</p>\n<ul class=\"fig-list\"><li>Obere Schicht (blau unterlegt, System-Services / Routing-Ebene): Enthält den Baustein <code>PDU Router</code>.\n</li><li>Mittlere Schicht (<em>Communication HW Abstraction</em>, grün unterlegt): Beinhaltet den Baustein <code>LIN Interface (incl. LinTp)</code>.\n</li><li>Untere Schicht (<em>Communication Drivers</em>, rot unterlegt): Beinhaltet zwei parallele Treiberinstanzen bzw. Module, <code>LIN Driver 1</code> und <code>LIN Driver 2</code>.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Verbindungspfade:</p>\n<ul class=\"fig-list\"><li>Ein vertikaler Doppelpfeil zwischen <code>PDU Router</code> und <code>LIN Interface (incl. LinTp)</code> ist mit <code>N-PDU</code> beschriftet.\n</li><li>Ein verzweigter Pfeil verbindet das <code>LIN Interface (incl. LinTp)</code> mit den beiden Treibern <code>LIN Driver 1</code> und <code>LIN Driver 2</code>; der Stamm dieses Verbindungspfads ist mit <code>L-PDU</code> beschriftet. Die Pfeilspitzen weisen nach oben zum LIN Interface sowie nach unten zu den jeweiligen LIN-Treibern.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne explizite zeitliche Sequenzabläufe. Die Pfeilverbindungen symbolisieren den bidirektionalen Datenaustausch von Protokolldateneinheiten (PDUs):</p>\n<ul class=\"fig-list\"><li>Austausch von Netzwerk-PDUs (<code>N-PDU</code>) in Sende- und Empfangsrichtung zwischen dem PDU Router und dem LIN Interface (inklusive LinTp).\n</li><li>Austausch von LIN-spezifischen Verbindungsdaten (<code>L-PDU</code>) zwischen dem LIN Interface und mehreren zugrunde liegenden LIN-Treibern (<code>LIN Driver 1</code>, <code>LIN Driver 2</code>) zur Anbindung mehrerer LIN-Kanäle oder -Controller.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Veranschaulicht die Integrationsgrenzen und Verantwortlichkeiten des LIN-Interface-Moduls in der AUTOSAR-Architektur. Das Modul kapselt die LIN-Treiber-Hardwareabstraktion sowie integrierte LinTp-Funktionalität und stellt dem PDU Router eine einheitliche PDU-Schnittstelle bereit. Die Verzweigung verdeutlicht die Multi-Channel-Fähigkeit bzw. die Unterstützung mehrerer Treiberinstanzen unterhalb eines einheitlichen Interfaces.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-a6be2eb29f45e3c9", "to": "FIG-5d2af1417ba579a7", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Beschriftung des Modulblocks in der Schicht <em>Communication HW Abstraction</em>: Die Benennung <code>LIN Interface (incl. LIN TP and LIN transceiver functionality)</code> wird zu <code>LIN Interface (incl. LinTp)</code> verkürzt.\n</li></ul>"}, {"from": "FIG-5d2af1417ba579a7", "to": "FIG-f172b47124306d00", "fr": "R3.0.7", "tr": "R3.1.5", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Beschriftung des rechten Treiberblocks in der Schicht <em>Communication Drivers</em>: Versehentliche Textergänzung und Beschneidung zu <code>LPduR_LinIfTxConfirmation(LinTxPduId)</code> über <code>IN Driver 2</code> statt <code>LIN Driver 2</code> (Grafik-/Satzfehler).\n</li></ul>"}, {"from": "FIG-f172b47124306d00", "to": "FIG-4e8873625241ef7c", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Beschriftung des rechten Treiberblocks in der Schicht <em>Communication Drivers</em>: Korrektur des Satzfehlers zurück zu <code>LIN Driver 2</code>; die fälschlich eingefügte Zeile <code>LPduR_LinIfTxConfirmation(LinTxPduId)</code> entfällt wieder.\n</li></ul>"}]};
